const nw = msg.data.new_state;
const ow = msg.data.old_state;
if (!nw || !nw.attributes || !nw.attributes.zebrania) return null;

const noweZebrania = nw.attributes.zebrania;
let stareZebrania = context.get('zebrania_id_cache') || (ow ? ow.attributes.zebrania : []);
context.set('zebrania_id_cache', noweZebrania);

const imie = nw.attributes.friendly_name?.replace('Zebrania: ', '') || "Uczeń";
let wiadomosci = [];

noweZebrania.forEach(z => {
    const juzBylo = stareZebrania.some(o => String(o.id) === String(z.id));
    if (!juzBylo) {
        const onlineInfo = z.online ? `\n**Link:** ${z.online}` : '';
        wiadomosci.push({
            payload: {
                title: `Nowe zebranie z rodzicami: ${imie}`,
                message: `### 📅 Zebranie z rodzicami\n**Data:** ${z.data || '—'}\n**Godzina:** ${z.godzina || '—'}\n**Sala:** ${z.sala || '—'}\n\n${z.opis || 'Brak opisu'}${onlineInfo}`,
                notification_id: "vultron_zebranie_" + z.id
            }
        });
    }
});

if (wiadomosci.length > 0) return [wiadomosci];
return null;
